  // corners (< 0.35 m) merge
  const all = [...routed, ...tail];
  const out: XZ[] = [all[0]];
  for (let i = 1; i < all.length; i++) {
    const p = all[i], q = out[out.length - 1];
    if (i < all.length - 1 && Math.hypot(p.x - q.x, p.z - q.z) < 0.35) continue;
    out.push(p);
  }
