export const _obsDebug = {route: (a: XZ, b: XZ, obs: Ob[]) => route(a, b, obs), obstaclesFor: (c: number, o: {stepH?: number; T?: number}) => obstaclesFor(c, o), crosses: (a: XZ, b: XZ, v: XZ[]) => crosses(a, b, v), inside: (p: XZ, v: XZ[]) => inside(p, v)};
